I think you have to explicitly add the model you want to use from that provider (probably because opencode doesn't know what models are provided by that provider and how to get the list either):
```
{
  "$schema": "https://opencode.ai/config.json",
  "provider": {
    "myprovider": {
      "npm": "@ai-sdk/openai-compatible",
      "name": "My AI ProviderDisplay Name",
      "options": {
        "baseURL": "https://api.myprovider.com/v1"
      },
      "models": { 👈🏽
        "my-model-name": {
          "name": "My Model Display Name"
        }
      }
    }
  }
}
```
